import threading, time
from inventory import Inventory, MemoryStore, OutOfStock

# 1. stress: 50 threads, mixed reserve/release over 5 skus, nothing goes negative
store = MemoryStore({f"S{i}": 200 for i in range(5)})
inv = Inventory(store)
taken = {f"S{i}": 0 for i in range(5)}
guard = threading.Lock()

def worker(n):
    for i in range(200):
        sku = f"S{(n + i) % 5}"
        try:
            left = inv.reserve(sku, 3)
            assert left >= 0, left
            with guard: taken[sku] += 3
        except OutOfStock:
            pass
        if i % 3 == 0:
            with guard:
                if taken[sku] >= 3: taken[sku] -= 3; ok = True
                else: ok = False
            if ok: inv.release(sku, 3)

ts = [threading.Thread(target=worker, args=(n,)) for n in range(50)]
for t in ts: t.start()
for t in ts: t.join()
snap = store.snapshot()
for sku, left in snap.items():
    assert left >= 0, (sku, left)
    assert left + taken[sku] == 200, (sku, left, taken[sku])
print("stress ok:", snap)

# 2. distinct skus still run concurrently (locks are per sku, not global)
class SlowStore(MemoryStore):
    def get(self, sku):
        v = super().get(sku); time.sleep(0.05); return v

inv2 = Inventory(SlowStore({f"K{i}": 10 for i in range(8)}))
start = time.perf_counter()
ts = [threading.Thread(target=inv2.reserve, args=(f"K{i}", 1)) for i in range(8)]
for t in ts: t.start()
for t in ts: t.join()
el = time.perf_counter() - start
print(f"8 distinct skus took {el:.3f}s (serial would be ~0.40s)")
assert el < 0.2, el
